  window.NewspapersData = {
    newspapers: newspapers,
    getByCountry: function(country) { return newspapers.filter(function(n) { return n.country === country; }); },
    getByCategory: function(cat) { return newspapers.filter(function(n) { return n.category === cat; }); },
    getSubscribed: function() { return newspapers.filter(function(n) { return n.isSubscribed; }); },
    getHighestRated: function(n) {
      n = n || 5;
      return newspapers.slice().sort(function(a, b) { return b.rating - a.rating; }).slice(0, n);
    },
    getMostSubscribed: function(n) {
      n = n || 5;
      return newspapers.slice().sort(function(a, b) { return parseFloat(b.subscribers) - parseFloat(a.subscribers); }).slice(0, n);
    },
    getById: function(id) { return newspapers.find(function(n) { return n.id === id; }); }
  };
